  private knowledgeOrchestrator: any = null
  private tray: Tray | null = null
  private updateAvailable: boolean = false
  private disguiseMode: 'terminal' | 'settings' | 'activity' | 'none' = 'none'

  // View management
  private view: "queue" | "solutions" = "queue"
  private isUndetectable: boolean = false
  // Workaround for macOS Sequoia / Electron 33 bug where setContentProtection
  // is silently ignored: poll for Zoom and hide the launcher entirely when
  // it's running. Window literally off-screen → guaranteed invisible in any
  // screen-capture path.
